 if(!d){addError('Unsupported company.');return base;}
 if(!state||state.enabled!==true||state.version!==d.version||state.ticker!==d.ticker)addError('Allocation identity/version is stale or not enabled.');
 if(draft.profileId!=='annual-research-v1'||draft.version!==d.draftVersion||(d.sourceSHA256&&draft.incrementalResearch?.sourceSHA256!==d.sourceSHA256))addError('Operating research source/version does not match the allocation definition.');
